#!/bin/bash
set -e

CONF=/etc/nginx/sites-enabled/app
INDEX=/srv/www/index.html

if [ ! -f "$INDEX" ]; then
    echo "Ошибка: файл $INDEX не найден" >&2
    exit 1
fi

# Резервная копия сломанной конфигурации (cp -L копирует содержимое, даже если это симлинк)
if [ -e "$CONF" ]; then
    cp -L "$CONF" "$CONF.broken.$(date +%s)"
    rm -f "$CONF"
fi

cat > "$CONF" <<'EOF'
server {
    listen 8080;
    server_name localhost;

    root /srv/www;
    index index.html;

    location / {
        try_files $uri $uri/ =404;
    }
}
EOF

nginx -t

# systemd нет: запускаем или перезагружаем nginx напрямую
if pgrep -x nginx >/dev/null; then
    nginx -s reload
else
    nginx
fi

sleep 1
curl -fsS http://localhost:8080/ >/dev/null && echo "OK: http://localhost:8080/ отвечает"
